//! Non-tautological cross-engine convergence: REAL yjs 13.6.30 update lineages
//! (committed fixtures, generated by `tests/fixtures/gen-fixtures.mjs`) driven
//! through the Rust durable append → reconstruct pipeline must converge on the
//! yjs-computed expectation. Fixtures come from yjs, not Rust round-tripped, so
//! a Rust regression cannot hide behind its own encoder (the spike + R08
//! pattern).
//!
//! Also proves, cross-engine: OffsetKind::Utf16 is load-bearing (a Bytes probe
//! diverges from yjs), nested-frontmatter key sorting (constraint 2), and
//! compaction convergence-neutrality against the yjs state.

mod common;

use common::*;
use dohc_engine_collab::{
    apply_remote_update, load_persisted, maybe_compact, record_local_update, ydoc::OffsetMode,
    CollabError, CompactOutcome, ContentKind, Regime, RemoteUpdate, ReplicationApplyOutcome, Ydoc,
};
use dohc_engine_storage::{NoFaults, TxnOutcome};

const OVERLAP_U1_HEX: &str = "01010c00040109706c61696e546578740461efbfbd00";
const OVERLAP_U2_HEX: &str = "01010c00040109706c61696e546578740561f09f988000";

fn decode_hex(encoded: &str) -> Vec<u8> {
    encoded
        .as_bytes()
        .chunks_exact(2)
        .map(|pair| {
            let pair = std::str::from_utf8(pair).expect("hex utf8");
            u8::from_str_radix(pair, 16).expect("hex byte")
        })
        .collect()
}

fn setup_parity_store(tag: &str, regime: Regime) -> (TempStore, dohc_engine_collab::DocKey) {
    let mut ts = fresh_store(tag);
    let key = test_key();
    seed_parents(&mut ts.store, &key, 1_000);
    dohc_engine_collab::ensure_marker(
        &mut ts.store,
        &key,
        ContentKind::Plaintext,
        regime,
        &NoFaults,
        1_000,
    )
    .expect("marker");
    (ts, key)
}

fn content_kind(fx: &Fixture) -> ContentKind {
    ContentKind::parse(&fx.content_kind)
}

/// Drive a fixture's yjs update lineage through the durable local-only pipeline
/// and return the reconstructed doc + how many updates landed.
fn ingest(fx: &Fixture) -> (TempStore, dohc_engine_collab::DocKey, i64) {
    let mut ts = fresh_store(&format!("xeng-{}", fx.seed));
    let key = test_key();
    seed_parents(&mut ts.store, &key, 1_000);
    dohc_engine_collab::ensure_marker(
        &mut ts.store,
        &key,
        content_kind(fx),
        Regime::LocalOnly,
        &NoFaults,
        1_000,
    )
    .expect("marker");
    let mut landed = 0i64;
    for (i, u) in fx.updates.iter().enumerate() {
        let bytes = decode_b64(u);
        let outcome = record_local_update(&mut ts.store, &key, &bytes, &NoFaults, 1_000 + i as i64)
            .expect("record");
        if let TxnOutcome::Committed(app) = outcome {
            if !app.deduped {
                landed += 1;
            }
        }
    }
    (ts, key, landed)
}

fn assert_matches_expectation(fx: &Fixture, doc: &Ydoc) {
    match content_kind(fx) {
        ContentKind::Plaintext => {
            let expected = fx.expected["text"].as_str().expect("text");
            assert_eq!(
                doc.plaintext_string(),
                expected,
                "plaintext seed {}",
                fx.seed
            );
            // The projection of a plaintext doc IS the exact text.
            assert_eq!(
                doc.project(ContentKind::Plaintext).markdown,
                expected,
                "plaintext projection seed {}",
                fx.seed
            );
        }
        ContentKind::Richdoc => {
            assert_eq!(
                doc.frontmatter_json(),
                fx.expected["frontmatter"],
                "frontmatter seed {}",
                fx.seed
            );
            let expected_paras = fx.expected["paragraphs"].as_array().expect("paras");
            let got = doc.body_paragraph_runs();
            assert_eq!(
                got.len(),
                expected_paras.len(),
                "paragraph count seed {}",
                fx.seed
            );
            for (pi, (para, exp)) in got.iter().zip(expected_paras).enumerate() {
                let exp_runs = exp["runs"].as_array().expect("runs");
                assert_eq!(
                    para.len(),
                    exp_runs.len(),
                    "run count seed {} para {}",
                    fx.seed,
                    pi
                );
                for (run, er) in para.iter().zip(exp_runs) {
                    assert_eq!(run.0, er["text"].as_str().unwrap_or(""), "run text");
                    assert_eq!(run.1, er["bold"].as_bool().unwrap_or(false), "run bold");
                    assert_eq!(run.2, er["italic"].as_bool().unwrap_or(false), "run italic");
                }
            }
        }
    }
}

#[test]
fn every_fixture_converges_on_yjs_expectation() {
    let fixtures = load_all_fixtures();
    let mut plaintext = 0;
    let mut richdoc = 0;
    for fx in &fixtures {
        // Probes have their own dedicated tests.
        if fx.kind.is_some() {
            continue;
        }
        let (ts, key, _landed) = ingest(fx);
        let persisted = load_persisted(&ts.store, &key)
            .expect("load")
            .expect("marker present");
        assert_matches_expectation(fx, &persisted.doc);
        match content_kind(fx) {
            ContentKind::Plaintext => plaintext += 1,
            ContentKind::Richdoc => richdoc += 1,
        }
    }
    // Guard against a silently-empty corpus.
    assert!(
        plaintext >= 20,
        "expected the plaintext corpus, got {plaintext}"
    );
    assert!(richdoc >= 20, "expected the richdoc corpus, got {richdoc}");
    eprintln!("cross-engine converged: {plaintext} plaintext + {richdoc} richdoc fixtures");
}

#[test]
fn compaction_is_convergence_neutral_against_yjs() {
    // For every fixture: reconstruct pre-compaction content, force a compaction
    // (threshold 1 folds the whole log into one snapshot), reconstruct again,
    // and assert the converged content is byte-identical AND still equals the
    // yjs expectation. A compacted snapshot must yield the same converged content
    // as the un-compacted log.
    let fixtures = load_all_fixtures();
    let mut compacted_count = 0;
    for fx in &fixtures {
        if fx.kind.is_some() || fx.updates.len() < 2 {
            continue;
        }
        let (mut ts, key, _) = ingest(fx);
        let before = load_persisted(&ts.store, &key)
            .expect("load")
            .expect("marker")
            .doc
            .canonical_content_sha256();

        let outcome = maybe_compact(&mut ts.store, &key, 1, &NoFaults, 5_000).expect("compact");
        assert!(
            matches!(outcome, TxnOutcome::Committed(_)),
            "compact committed seed {}",
            fx.seed
        );
        // The update log is now folded away; a single snapshot remains.
        assert_eq!(
            count(&ts.store, "ydoc_updates", &key),
            0,
            "log pruned seed {}",
            fx.seed
        );
        assert_eq!(
            count(&ts.store, "ydoc_snapshots", &key),
            1,
            "one snapshot seed {}",
            fx.seed
        );

        let persisted = load_persisted(&ts.store, &key)
            .expect("load")
            .expect("marker");
        assert_eq!(
            persisted.doc.canonical_content_sha256(),
            before,
            "compaction changed converged content seed {}",
            fx.seed
        );
        assert_matches_expectation(fx, &persisted.doc);
        compacted_count += 1;
    }
    assert!(
        compacted_count >= 30,
        "compacted {compacted_count} fixtures"
    );
    eprintln!("compaction convergence-neutral across {compacted_count} fixtures");
}

#[test]
fn merged_update_reconstructs_identical_content() {
    // `merge_updates` (the compaction primitive the spike verified) over a
    // fixture's whole yjs log reconstructs identical content to the sequential
    // log — cross-checked against the yjs-authored `mergedUpdateB64`.
    for fx in load_all_fixtures() {
        let Some(merged_b64) = &fx.merged_update_b64 else {
            continue;
        };
        // Rust-side merge of the log.
        let log: Vec<Vec<u8>> = fx.updates.iter().map(|u| decode_b64(u)).collect();
        let rust_merged = dohc_engine_collab::merge_updates(&log).expect("merge");
        let doc_rust = Ydoc::wire();
        doc_rust.apply(&rust_merged).expect("apply rust merge");

        // yjs-side merge (authored in the fixture).
        let doc_yjs = Ydoc::wire();
        doc_yjs
            .apply(&decode_b64(merged_b64))
            .expect("apply yjs merge");

        assert_eq!(
            doc_rust.canonical_content_sha256(),
            doc_yjs.canonical_content_sha256(),
            "rust-merge vs yjs-merge diverged, seed {}",
            fx.seed
        );
    }
}

#[test]
fn offset_kind_utf16_is_load_bearing() {
    // The pinned OffsetKind probe. Seed a Utf16 doc AND a Bytes doc from the SAME
    // real yjs base update ("😀XYZ"), then do the identical LOCAL insert of "!" at
    // UTF-16 index 4 on each. yjs measures in UTF-16, so its expectation is
    // "😀XY!Z": the Utf16 doc MUST match yjs; the Bytes doc (index 4 = byte 4 =
    // before "X") MUST diverge. This is the concrete divergence the spike found.
    let fx = load_fixture("offsetProbe");
    let base = decode_b64(fx.base_update_b64.as_ref().expect("base"));
    let expected = fx.expected["textAfterInsertAt4"]
        .as_str()
        .expect("expected");
    let insert = fx.expected["insertChar"].as_str().unwrap_or("!");
    let index = fx.expected["insertIndex"].as_u64().unwrap_or(4) as u32;

    let utf16 = Ydoc::with_mode(OffsetMode::Utf16);
    utf16.apply(&base).expect("apply base utf16");
    utf16.plaintext_insert(index, insert);

    let bytes = Ydoc::with_mode(OffsetMode::Bytes);
    bytes.apply(&base).expect("apply base bytes");
    bytes.plaintext_insert(index, insert);

    assert_eq!(
        utf16.plaintext_string(),
        expected,
        "Utf16 doc must match the yjs UTF-16 placement"
    );
    assert_ne!(
        bytes.plaintext_string(),
        expected,
        "Bytes doc must diverge from yjs — proving Utf16 is required at the boundary"
    );
    eprintln!(
        "offset probe: utf16={:?} (==yjs) bytes={:?} (diverges)",
        utf16.plaintext_string(),
        bytes.plaintext_string()
    );
}

#[test]
fn surrogate_split_diverges_proving_wellformed_boundary_is_load_bearing() {
    // Binding constraint 3. yjs sanitizes a surrogate-pair-splitting edit into
    // U+FFFD (its string stays well-formed); yrs cannot represent the split the
    // same way, so the Rust reconstruction DIVERGES from yjs's UTF-16 units.
    // This pins that the R11b live adapter's isWellFormed() boundary check is
    // load-bearing: a surrogate-splitting edit must be rejected/sanitized BEFORE
    // it enters a lineage a Rust peer must replay.
    let fx = load_fixture("surrogateProbe");
    let doc = Ydoc::wire();
    for u in &fx.updates {
        doc.apply(&decode_b64(u)).expect("apply");
    }
    let rust_units: Vec<u64> = doc
        .plaintext_string()
        .encode_utf16()
        .map(u64::from)
        .collect();
    let yjs_units: Vec<u64> = fx.expected["yjsText"]
        .as_array()
        .expect("yjsText")
        .iter()
        .map(|v| v.as_u64().expect("unit"))
        .collect();
    assert_ne!(
        rust_units, yjs_units,
        "a surrogate-split must diverge — the boundary must reject it (constraint 3)"
    );
    eprintln!("surrogate probe: rust={rust_units:?} diverges from yjs={yjs_units:?}");
}

#[test]
fn replay_parity_gate_rejects_surrogate_probe_bypass1_before_journal() {
    let fx = load_fixture("surrogateProbe");
    let mut ts = fresh_store("surrogate-parity-gate");
    let key = test_key();
    seed_parents(&mut ts.store, &key, 1_000);
    dohc_engine_collab::ensure_marker(
        &mut ts.store,
        &key,
        ContentKind::Plaintext,
        Regime::LocalOnly,
        &NoFaults,
        1_000,
    )
    .expect("marker");
    let base = decode_b64(&fx.updates[0]);
    record_local_update(&mut ts.store, &key, &base, &NoFaults, 1_001).expect("base");

    let bypass = decode_b64(&fx.updates[1]);
    let bypass_sha = dohc_engine_collab::hex_sha256(&bypass);
    let error = record_local_update(&mut ts.store, &key, &bypass, &NoFaults, 1_002)
        .expect_err("surrogate split must fail closed");
    assert!(matches!(error, CollabError::ReplayParityViolation { .. }));
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 1);
    assert!(
        ts.store
            .get_binary_blob(&bypass_sha)
            .expect("blob lookup")
            .is_none(),
        "rejected update must not reach the blob store"
    );
}

#[test]
fn replay_parity_rejects_overlap_slice_divergence_on_local_path() {
    let (mut ts, key) = setup_parity_store("overlap-slice-local", Regime::LocalOnly);
    let u1 = decode_hex(OVERLAP_U1_HEX);
    record_local_update(&mut ts.store, &key, &u1, &NoFaults, 1_001)
        .expect("clean U+FFFD base must be accepted");
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 1);

    let u2 = decode_hex(OVERLAP_U2_HEX);
    let u2_sha = dohc_engine_collab::hex_sha256(&u2);
    let error = record_local_update(&mut ts.store, &key, &u2, &NoFaults, 1_002)
        .expect_err("overlap slice must fail closed");
    assert!(matches!(error, CollabError::ReplayParityViolation { .. }));
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 1);
    assert!(
        ts.store
            .get_binary_blob(&u2_sha)
            .expect("blob lookup")
            .is_none(),
        "rejected overlap update must not reach the blob store"
    );
}

